// Junta perfil + cv (vindos do Drive) com cada vaga.
const perfilNode = $('Drive: ler perfil.md').first();
const cvNode = $('Drive: ler curriculo.md').first();
const perfil_md = perfilNode?.binary?.data ? Buffer.from(perfilNode.binary.data.data, 'base64').toString('utf-8') : '';
const curriculo_md = cvNode?.binary?.data ? Buffer.from(cvNode.binary.data.data, 'base64').toString('utf-8') : '';
const jobs = $('Postgres: vagas não avaliadas').all();
return jobs.map(j => ({ json: { ...j.json, perfil_md, curriculo_md } }));

