// Parse JSON da resposta da OpenAI.
const items = $input.all();
const out = [];
for (const it of items) {
  const jobId = $('Merge perfil + cv + vaga').itemMatching(it.itemIndex).json.id;
  const text = it.json.choices?.[0]?.message?.content ?? '{}';
  let parsed = { score: 0, summary: 'parse_failed' };
  try { parsed = JSON.parse(text); } catch (e) { parsed.summary = 'json_parse_error: ' + e.message; }
  // Pricing aproximado gpt-4o-mini: $0.15 input / $0.60 output por 1M tokens
  const usage = it.json.usage || {};
  out.push({ json: {
    job_id: jobId,
    score: parsed.score,
    requirements_met: JSON.stringify(parsed.requirements_met || []),
    requirements_gap: JSON.stringify(parsed.requirements_gap || []),
    summary: parsed.summary,
    llm_model: it.json.model || 'unknown',
    llm_cost_usd: ((usage.prompt_tokens || 0) * 0.15 + (usage.completion_tokens || 0) * 0.60) / 1e6
  }});
}
return out;
